		r.URL.Scheme = targetURL.Scheme
		r.URL.Host = targetURL.Host
		// Use the target's path as the request path (so full paths like /v1/chat/completions are honored)
		r.URL.Path = targetURL.Path
		r.Host = targetURL.Host

